const e={web3_267:{lianjieqianbao:"Wallet verbinden",wodeqianbaodizhi:"Meine Wallet-Adresse",licai:"Mining",jinrulicai:"Mining betreten",yishouyi:"Erzielte Erträge",shouyilv:"Rendite",zhiyajine:"Mining-Betrag",canyu:"Teilnehmen",shouyishijian:"Ertragszeit {amount}/{time}",yifafangshouyi:"Ausgezahlte Erträge",licaishuju:"Mining-Daten",zongchanliang:"Gesamtausstoß",youxiaojiedian:"Gültige Knoten",canyuzhe:"Teilnehmer",yonghushouru:"Benutzereinkommen",liudongxinglicaishouyi:"Liquiditäts-Mining-Erträge",shouyi:"Erträge",licaishuoming:"Mining-Erklärung",weishenmeyaolicai:"Warum minen?",weishenmeyaolicai_desc:"Mining ist der Prozess der Vermögenssteigerung durch angemessene Kapitalallokation und den Einsatz verschiedener Finanzinstrumente. Effektives Mining kann Inflation entgegenwirken, passives Einkommen erhöhen, finanzielle Freiheit erreichen und frühe Pensionierung ermöglichen.",licaifengxian:"Welche Risiken hat Mining?",licaifengxian_desc:"Mining-Risiken umfassen Marktrisiken, Inflationsrisiken, Liquiditätsrisiken, Kreditrisiken und operationelle Risiken. Investoren sollten Produkte nach ihrer Risikotoleranz auswählen und durch Diversifizierung Risiken reduzieren.",xinshoruhekaishilicai:"Wie können Anfänger mit dem Mining beginnen?",xinshoruhekaishilicai_desc:"Anfänger sollten zuerst einen Notfallfonds aufbauen, ihre finanzielle Situation verstehen, Ziele setzen, grundlegende Investmentkenntnisse erwerben, mit risikoarmen Produkten starten, ihr Portfolio schrittweise erweitern und kontinuierlich lernen und Strategien anpassen.",qukuailianlicai_youshi:"Welche Vorteile hat Blockchain-Mining?",qukuailianlicai_youshi_desc:"Blockchain-Mining bietet Vorteile wie Dezentralisierung, hohe Transparenz, geringe Transaktionskosten, weltweite Zugänglichkeit und automatische Ausführung durch Smart Contracts und liefert innovative Lösungen für den traditionellen Mining-Markt.",liudongxingzhiyashishenme:"Was ist Liquiditäts-Mining?",liudongxingzhiyashishenme_desc:"Liquiditäts-Mining ist der Prozess, bei dem Krypto-Assets in einem DeFi-Protokoll gesperrt werden, um Liquidität bereitzustellen und gleichzeitig Belohnungen zu erhalten. Miner erhalten normalerweise Transaktionsgebührenanteile und Governance-Token-Belohnungen, was eine beliebte Methode für passives Einkommen ist.",ruhepinggulicaichanpindefengxian:"Wie bewertet man die Risiken von Mining-Produkten?",ruhepinggulicaichanpindefengxian_desc:"Bei der Bewertung von Mining-Produkten sollten Faktoren wie Ertragsschwankungen, historische Performance, Liquidität, Reputation des Emittenten, Investitionsdauer und Marktumfeld berücksichtigt werden, kombiniert mit der eigenen Risikotoleranz.",shouyibiao:"Ertragstabelle",meirishouyi:"Tägliche Erträge"}};export{e as default};
